# v15.1: version 15, four default tabs, merchant placeholder and list, group headers, items buttons, Paid for Others editor
from playwright.sync_api import sync_playwright
CSV='/home/claude/Transactions.csv'; res=[]
def ok(n,c): res.append(bool(c)); print(('PASS ' if c else 'FAIL ')+n)
with sync_playwright() as p:
    b=p.chromium.launch(); ctx=b.new_context(viewport={'width':390,'height':844},service_workers='block'); pg=ctx.new_page(); errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://localhost:8123/'); pg.wait_for_selector('#first-file',state='attached')
    pg.set_input_files('#first-file',CSV); pg.wait_for_selector('#setup',timeout=20000); pg.click('#setup .btn'); pg.wait_for_timeout(900)
    J=lambda js: pg.evaluate("(async()=>{const c=await import('/js/core.js');"+js+"})()")
    J("c.commit(d=>{d.settings.mode='advanced';delete d.settings.tabs;const home=d.settings.homeCur||'PHP';d.accounts.push(c.stamp({id:'w1',name:'Wallet One',cur:home,type:'cash',open:5000,include:true,archived:false}));for(const [i,n] of [['pa','Ana'],['pb','Ben']])d.accounts.push(c.stamp({id:i,name:n,cur:home,type:'owed',open:0,include:true,archived:false}))})")
    ok('version starts with 15', pg.evaluate("(async()=>(await import('/js/version.js')).versionText())()").startswith('15.'))
    ok('four default tabs', pg.evaluate("(async()=>(await import('/js/screens.js')).DEFAULT_TABS.length)()")==4)
    J("c.commit(d=>{for(let i=0;i<40;i++)d.txs.push(c.stamp({id:'mm'+i,kind:'expense',date:'2026-10-01',name:'X'+i,amount:10,cur:d.accounts.find(a=>a.id==='w1').cur,fx:1,acct:'w1',merchant:'Shop '+i}))})")
    pg.evaluate("document.querySelector('[data-act=add]').click()"); pg.wait_for_selector('#entry'); pg.wait_for_timeout(400)
    pg.fill('#f-what','Lunch'); pg.evaluate("(()=>{const e=document.querySelector('#f-acct');e.value='w1';e.dispatchEvent(new Event('change',{bubbles:true}))})()"); pg.fill('#f-amount','900'); pg.wait_for_timeout(300)
    ok('merchant placeholder', 'e.g. 7-Eleven, Starbucks, McDo, ...' in pg.inner_text('[data-e=merchpick]'))
    pg.evaluate("document.querySelector('[data-e=merchpick]').click()"); pg.wait_for_selector('.mpr'); pg.wait_for_timeout(300)
    r=pg.evaluate("(()=>{const l=document.querySelector('#mlist'),cs=getComputedStyle(l);return [cs.overflowY,l.scrollHeight>l.clientHeight,getComputedStyle(document.querySelector('.mpr .rmain strong')).justifyContent]})()")
    ok('merchant list scrolls by itself and is left aligned %s'%r, r[0]=='auto' and r[1] and r[2] in ('flex-start','start'))
    pg.evaluate("document.querySelector('#mlist').scrollTop=300"); pg.wait_for_timeout(100)
    ok('list scrolled', pg.evaluate("document.querySelector('#mlist').scrollTop")>0)
    pg.keyboard.press('Escape'); pg.wait_for_timeout(300)
    if pg.locator('.mpr').count(): pg.evaluate("document.querySelector('.sheet [data-close], .sheet .close')&&document.querySelector('.sheet [data-close], .sheet .close').click()"); pg.wait_for_timeout(300)
    # items buttons
    pg.evaluate("document.querySelector('[data-e=items-on]').click()"); pg.wait_for_timeout(300)
    h=pg.evaluate("""(()=>{const g=(s)=>document.querySelector(s).getBoundingClientRect(),row=g('.items .item'),n=g('.items .item .in-n'),a=g('.items .item .inamt'),q=g('.items .item .qty'),bs=[...document.querySelectorAll('.items .item .qty button')].map(x=>x.getBoundingClientRect().width),c=g('.items .item .in-c, .items .item .picbtn');return {w:row.width,n:n.width/row.width,a:a.width/row.width,q:q.width/row.width,b:bs.map(x=>x/row.width),ah:a.height,qh:q.height,top:g('.itembox .othhead').top<g('.items .item').top,cancel:!!document.querySelector('.itembox [data-e=items-off]'),x:document.querySelectorAll('.itembox .item .iconbtn').length}})()""")
    ok('Item and Amount about 60 percent, quantity about 40 percent, buttons narrow %s'%h, 0.55<=h['n']<=0.65 and 0.55<=h['a']<=0.65 and 0.35<=h['q']<=0.45 and all(x<=0.2 for x in h['b']) and abs(h['ah']-h['qh'])<=2)
    ok('Cancel on top like Paid for Others, no X', h['top'] and h['cancel'] and h['x']==0)
    pg.evaluate("document.querySelector('[data-e=items-off]').click()"); pg.wait_for_timeout(200)
    ok('Cancel closes the split section', pg.locator('.itembox').count()==0 and pg.locator('[data-e=items-on]').count()==1)
    pg.evaluate("document.querySelector('[data-e=items-on]').click()"); pg.wait_for_timeout(200)
    pg.locator('.itembox').scroll_into_view_if_needed(); pg.locator('.itembox').screenshot(path='/tmp/items.png')
    pg.evaluate("document.querySelector('[data-e=item-del]').click()"); pg.wait_for_timeout(200)
    # paid for others
    pg.evaluate("document.querySelector('[data-e=oth-on]').click()"); pg.wait_for_timeout(300)
    ok('Cancel is at the top, no bottom link', pg.evaluate("(()=>{const b=document.querySelector('#othbox [data-e=oth-off]');return !!b&&b.textContent.trim()==='Cancel'&&b.getBoundingClientRect().top<document.querySelector('#othbox .othmode').getBoundingClientRect().top})()") and 'Not paid for others' not in pg.inner_text('#othbox'))
    pg.evaluate("document.querySelector('[data-e=oth-mode][data-v=amount]').click()"); pg.wait_for_timeout(200)
    pg.locator('.oth-who').nth(0).select_option('pa'); pg.wait_for_timeout(300); pg.evaluate("document.querySelector('[data-e=oth-add]').click()"); pg.wait_for_timeout(300)
    o2=pg.evaluate("[...document.querySelectorAll('.oth-who')[1].options].map(o=>o.value)")
    ok('chosen person not offered again %s'%o2, 'pa' not in o2 and 'pb' in o2)
    g=pg.evaluate("(()=>{const r=document.querySelector('.othrow'),s=r.querySelector('.oth-who,.acctbtn').getBoundingClientRect(),a=r.querySelector('.oth-n').getBoundingClientRect();return [Math.round(s.height),Math.round(a.height),Math.round(s.width),Math.round(a.width)]})()")
    ok('selector and amount same height, amount wider %s'%g, g[0]==g[1] and g[3]>g[2])
    pg.fill('.othrow .oth-n','100+50'); pg.evaluate("document.querySelector('.othrow [data-e=oth-calc]').click()"); pg.wait_for_timeout(300)
    ok('calculator in the amount field', pg.input_value('.othrow .oth-n')=='150')
    pg.evaluate("document.querySelector('[data-e=oth-mode][data-v=pct]').click()"); pg.wait_for_timeout(200)
    ok('percent input has the calculator too', pg.locator('.othrow .calcin').count()>=1)
    pg.evaluate("document.querySelector('#othbox [data-e=oth-off]').click()"); pg.wait_for_timeout(200)
    ok('Cancel closes the editor', pg.locator('#othbox').count()==0)
    ok('no errors %s'%errs, not errs)
print('fails',res.count(False))
